<?php
namespace App\Jobs;use App\Models\Resume;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Storage;use Symfony\Component\Process\ExecutableFinder;use Symfony\Component\Process\Process;
class ParseCandidateResume implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=2;public function __construct(public int $resumeId){}public function handle():void{$resume=Resume::with('profile.user')->find($this->resumeId);if(!$resume)return;$resume->update(['parsing_status'=>'processing','parse_error'=>null]);try{$text=$this->extractText(Storage::disk($resume->disk)->path($resume->path));preg_match('/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i',$text,$email);preg_match('/(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{2,4}\)?[\s.-]?)?\d{6,10}/',$text,$phone);preg_match('/(\d{1,2}(?:\.\d+)?)\s*\+?\s*(?:years?|yrs?)/i',$text,$experience);$known=config('recruitment.skills',[]);$skills=collect($known)->filter(fn($skill)=>preg_match('/(?<![A-Za-z0-9])'.preg_quote($skill,'/').'(?![A-Za-z0-9])/i',$text))->values()->take(40)->all();$education=$this->matchingLine($text,'/(b\.?tech|m\.?tech|bca|mca|bachelor|master|degree|university|college)/i');$designation=$this->matchingLine($text,'/(developer|engineer|analyst|architect|manager|consultant|designer|tester)/i');$data=['name'=>$resume->profile->user->name,'email'=>$email[0]??$resume->profile->user->email,'phone'=>isset($phone[0])?trim($phone[0]):$resume->profile->phone,'skills'=>$skills,'experience'=>isset($experience[1])?(float)$experience[1]:null,'education'=>$education,'designation'=>$designation,'companies'=>[]];$updates=[];foreach(['phone'=>'phone','experience'=>'experience_years','education'=>'education','designation'=>'current_designation'] as $source=>$target){if(blank($resume->profile->{$target})&&filled($data[$source]??null))$updates[$target]=$data[$source];}if(blank($resume->profile->preferred_role)&&$designation)$updates['preferred_role']=$designation;if($updates){$current=$resume->profile->toArray();$updates['profile_completion']=$this->completion($updates+$current);$resume->profile->update($updates);}$resume->update(['parsing_status'=>($email||$phone||$skills||$education)?'processed':'needs_review','parsed_data'=>$data,'parsed_at'=>now()]);}catch(\Throwable $e){$resume->update(['parsing_status'=>'failed','parse_error'=>substr($e->getMessage(),0,2000)]);throw $e;}}
private function extractText(string $path):string{$binary=(new ExecutableFinder)->find('pdftotext');if(!$binary)throw new \RuntimeException('PDF text extractor is not installed.');$process=new Process([$binary,'-layout','-enc','UTF-8',$path,'-']);$process->setTimeout(30);$process->mustRun();return trim($process->getOutput());}
private function matchingLine(string $text,string $pattern):?string{foreach(preg_split('/\R/',$text) as $line){$line=trim(preg_replace('/\s+/',' ',$line));if(strlen($line)>=4&&strlen($line)<=180&&preg_match($pattern,$line))return $line;}return null;}
private function completion(array $d):int{$fields=['first_name','last_name','phone','address','headline','bio','current_company','current_designation','experience_years','expected_salary','notice_period','location'];return (int)round(collect($fields)->filter(fn($f)=>filled($d[$f]??null))->count()/count($fields)*100);}}
